export async function upsertCustomerProfile(userId: number, input: { restaurantId?: number | null; slug?: string; isPublic?: boolean; displayName?: string | null; title?: string | null; bio?: string | null; avatarUrl?: string | null; coverUrl?: string | null; phone?: string | null; whatsapp?: string | null; email?: string | null; websiteUrl?: string | null; address?: string | null; city?: string | null; instagramUrl?: string | null; twitterUrl?: string | null; facebookUrl?: string | null; linkedinUrl?: string | null; servicesJson?: string | null }) { const db = await getDb(); if (!db) throw new Error("Database is not available"); const existing = await getCustomerProfile(userId); if (existing) { await db.update(customerProfiles).set({ ...input, updatedAt: new Date() }).where(eq(customerProfiles.userId, userId)); return existing.id; } const result = await db.insert(customerProfiles).values({ userId, slug: input.slug ?? `customer-${userId}-${nanoid(8)}`, isPublic: input.isPublic ?? false, ...input }); return Number(result[0].insertId); }

